CREATE TABLE "grupo_empresa" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar
);

CREATE TABLE "usuario" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar,
  "email" varchar UNIQUE,
  "grupo_empresa_id" integer NOT NULL,
  "papel" varchar
);

CREATE TABLE "sla_categoria" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "produto" varchar,
  "categoria" varchar,
  "prioridade" varchar,
  "tempo_resposta" integer,
  "tempo_resolucao" integer
);

CREATE TABLE "chamado" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo_publico" varchar UNIQUE,
  "usuario_id" integer NOT NULL,
  "grupo_empresa_id" integer NOT NULL,
  "sla_categoria_id" integer NOT NULL,
  "produto" varchar,
  "categoria" varchar,
  "status" varchar,
  "prioridade" varchar,
  "sla_prazo" timestamp,
  "criado_em" timestamp,
  "fechado_em" timestamp
);

CREATE TABLE "interacao" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "usuario_id" integer NOT NULL,
  "chamado_id" integer NOT NULL,
  "tipo" varchar,
  "mensagem" text,
  "criado_em" timestamp
);

CREATE TABLE "anexo" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "interacao_id" integer NOT NULL,
  "nome_arquivo" varchar,
  "url" varchar,
  "tamanho_bytes" integer
);

CREATE TABLE "log_auditoria" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "chamado_id" integer NOT NULL,
  "usuario_id" integer NOT NULL,
  "acao" varchar,
  "campo_alterado" varchar,
  "valor_anterior" text,
  "valor_novo" text,
  "data" timestamp
);

COMMENT ON COLUMN "usuario"."papel" IS 'cliente, agente, supervisor, admin';

COMMENT ON COLUMN "chamado"."status" IS 'aberto, em_andamento, aguardando_cliente, resolvido, fechado';

COMMENT ON COLUMN "interacao"."tipo" IS 'publica, nota_interna';

ALTER TABLE "usuario" ADD FOREIGN KEY ("grupo_empresa_id") REFERENCES "grupo_empresa" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "chamado" ADD FOREIGN KEY ("usuario_id") REFERENCES "usuario" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "chamado" ADD FOREIGN KEY ("grupo_empresa_id") REFERENCES "grupo_empresa" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "chamado" ADD FOREIGN KEY ("sla_categoria_id") REFERENCES "sla_categoria" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "interacao" ADD FOREIGN KEY ("chamado_id") REFERENCES "chamado" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "interacao" ADD FOREIGN KEY ("usuario_id") REFERENCES "usuario" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "anexo" ADD FOREIGN KEY ("interacao_id") REFERENCES "interacao" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "log_auditoria" ADD FOREIGN KEY ("chamado_id") REFERENCES "chamado" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "log_auditoria" ADD FOREIGN KEY ("usuario_id") REFERENCES "usuario" ("id") DEFERRABLE INITIALLY IMMEDIATE;
